const ECONOMY_CHAPTERS=[
  {id:'basics',icon:'📊',title:'Basics of Economics',
   notes:[
    {h:'What is Economics?',items:['Economics is the study of how individuals, firms, and governments allocate <b>scarce resources</b> to satisfy unlimited wants','<b>Microeconomics</b>: studies individual units — consumer, firm, household; demand, supply, price; "bottom-up" view','<b>Macroeconomics</b>: studies economy as a whole — national income, inflation, unemployment, growth; "top-down" view']},
    {h:'Types of Economic Systems',items:['<b>Capitalist Economy</b>: resources owned/controlled by private individuals; driven by market forces (USA)','<b>Socialist/Command Economy</b>: resources owned and allocated by the State (former USSR, Cuba)','<b>Mixed Economy</b>: co-existence of public and private sectors — India follows a mixed economy']},
    {h:'Sectors & Key Terms',items:['<b>Primary Sector</b>: agriculture, forestry, fishing, mining','<b>Secondary Sector</b>: manufacturing, construction, industry','<b>Tertiary Sector</b>: services — banking, trade, transport, IT','<b>Quaternary Sector</b>: knowledge-based — R&D, consulting, IT-enabled services','📌 EXAM TIP: Tertiary (Services) contributes highest share to India\'s GDP; Primary sector employs the largest share of workforce — classic structural mismatch','<b>Opportunity Cost</b>: value of next-best alternative foregone','<b>Fiscal Policy</b>: government\'s policy on taxation & spending (Finance Ministry)','<b>Monetary Policy</b>: central bank\'s policy on money supply & interest rates (RBI)']}
   ],
   pyqs:[
    {q:'Which sector contributes the highest share to India\'s GDP?',opts:['Primary (Agriculture)','Secondary (Industry)','Tertiary (Services)','Quaternary (Knowledge)'],ans:2,exp:'The Tertiary (Services) sector contributes the highest share to India\'s GDP — approximately 55–60%. This includes IT/ITeS, banking, trade, tourism, and real estate. The Primary sector, though employing the most people, contributes the least to GDP — a classic case of structural mismatch.',yr:'UPSC 2019'},
    {q:'India follows which type of economic system?',opts:['Purely capitalist','Purely socialist/command','Mixed economy','Laissez-faire'],ans:2,exp:'India follows a mixed economy, where both the public sector and private sector coexist. The public sector undertakes strategic and welfare activities, while private enterprise operates in other sectors. This was the framework adopted since the 1950s and continued after 1991 reforms.',yr:'UPSC 2017'}
   ]},
  {id:'nationalincome',icon:'💹',title:'National Income Accounting (GDP, GNP, NNP)',
   notes:[
    {h:'Key Aggregates',items:['<b>GDP (Gross Domestic Product)</b>: total value of goods & services produced <b>within a country\'s borders</b> in a year, regardless of who produces it. Formula: <b>GDP = C + I + G + (X − M)</b>','<b>GNP (Gross National Product)</b>: GDP + Net income from abroad (income earned by residents abroad − income earned by foreigners domestically)','<b>NNP (Net National Product)</b>: GNP − Depreciation (wear & tear of capital)','<b>NDP (Net Domestic Product)</b>: GDP − Depreciation','<b>Per Capita Income</b>: National Income ÷ Total Population','📌 NNP at factor cost = <b>National Income</b> of a country; released by NSO (MoSPI)']},
    {h:'Real vs Nominal GDP',items:['<b>Nominal GDP</b>: calculated at current market prices (includes inflation effect)','<b>Real GDP</b>: calculated at constant/base-year prices (inflation removed) — better indicator of actual growth','<b>GDP Deflator</b> = (Nominal GDP ÷ Real GDP) × 100','India\'s current GDP <b>base year: 2011–12</b>; from 2026, new base year: <b>2022–23</b>']},
    {h:'Methods of Measuring National Income',items:['<b>Product/Output Method</b>: sums value added at each stage of production','<b>Income Method</b>: sums all factor incomes — wages, rent, interest, profit','<b>Expenditure Method</b>: sums all spending — C + I + G + Net exports','<b>Green GDP</b>: GDP adjusted for environmental degradation and depletion of natural resources']}
   ],
   pyqs:[
    {q:'Which is a better indicator of actual economic growth — Nominal GDP or Real GDP?',opts:['Nominal GDP, as it reflects current prices','Real GDP, as it removes the effect of inflation','Both are equally good','Neither; GNP is the best indicator'],ans:1,exp:'Real GDP is the better indicator of actual economic growth because it is calculated at constant/base-year prices, removing the effect of inflation. Nominal GDP can rise simply because prices have increased, even if actual production has not grown.',yr:'UPSC 2018'},
    {q:'The GDP formula C + I + G + (X − M) uses the:',opts:['Income method','Output/Product method','Expenditure method','Value-added method'],ans:2,exp:'The formula GDP = C + I + G + (X − M) represents the Expenditure Method of measuring GDP. C = Private Consumption, I = Investment, G = Government Spending, X = Exports, M = Imports. This is the most commonly used method in practice.',yr:'UPSC 2020'}
   ]},
  {id:'banking',icon:'🏦',title:'Money, Banking & RBI',
   notes:[
    {h:'Reserve Bank of India (RBI)',items:['Established <b>1 April 1935</b> under RBI Act, 1934; nationalized in <b>1949</b>; headquartered in <b>Mumbai</b>','Issues currency notes (sole authority; except ₹1 coin/note issued by Finance Ministry)','Banker to the Government & banker\'s bank; manages forex reserves; regulates banks & NBFCs']},
    {h:'Monetary Policy Tools',items:['<b>Repo Rate</b>: rate at which RBI lends short-term funds to commercial banks','<b>Reverse Repo Rate</b>: rate at which RBI borrows from commercial banks','<b>CRR (Cash Reserve Ratio)</b>: % of deposits banks must keep as cash reserve with RBI (unremunerated)','<b>SLR (Statutory Liquidity Ratio)</b>: % of deposits banks must maintain in liquid assets (cash, gold, govt securities)','<b>Bank Rate</b>: rate at which RBI lends long-term funds to banks','<b>MSF (Marginal Standing Facility)</b>: emergency overnight borrowing; slightly above Repo rate','<b>OMO (Open Market Operations)</b>: RBI buying/selling govt securities to manage liquidity','📌 Monetary policy decisions taken by <b>MPC (Monetary Policy Committee)</b> — 6-member body (3 RBI + 3 external) headed by RBI Governor; <b>Inflation target: 4% (±2%)</b> under flexible inflation targeting']},
    {h:'Types of Money & Banking Structure',items:['<b>M1 (Narrow Money)</b>: currency with public + demand deposits + other deposits with RBI','<b>M3 (Broad Money)</b>: M1 + time deposits with banks (most widely used measure)','<b>Scheduled Banks</b>: listed in 2nd Schedule of RBI Act — Commercial Banks (Public, Private, Foreign, RRBs) & Cooperative Banks','<b>NBFCs</b>: Non-Banking Financial Companies — banking-like services but cannot accept demand deposits or issue cheques','<b>Payments Banks & Small Finance Banks</b>: niche banking models for financial inclusion (e.g., Airtel Payments Bank)']}
   ],
   pyqs:[
    {q:'The Monetary Policy Committee (MPC) of the RBI consists of how many members?',opts:['3','4','6','8'],ans:2,exp:'The MPC consists of 6 members — 3 from the RBI (Governor as Chairperson, Deputy Governor, and one other official) and 3 external members appointed by the Government. The RBI Governor has the casting vote in case of a tie.',yr:'UPSC 2019'},
    {q:'RBI\'s inflation target under the flexible inflation targeting framework is based on which index?',opts:['WPI (Wholesale Price Index)','CPI (Consumer Price Index)','GDP Deflator','PPI (Producer Price Index)'],ans:1,exp:'RBI\'s inflation target is based on CPI (Consumer Price Index) — Combined. The target is 4% with a band of ±2% (i.e., between 2% and 6%). This was formalized under the Monetary Policy Framework Agreement (2015) and the RBI Act amendment (2016).',yr:'UPSC 2018'},
    {q:'The Cash Reserve Ratio (CRR) must be maintained with:',opts:['State Bank of India','Securities and Exchange Board of India','Reserve Bank of India','Finance Ministry'],ans:2,exp:'The Cash Reserve Ratio (CRR) is the portion of a bank\'s total deposits that must be maintained as cash with the Reserve Bank of India. It is one of the key monetary policy instruments used by RBI to control liquidity in the banking system.',yr:'UPSC 2017'}
   ]},
  {id:'inflation',icon:'📉',title:'Inflation & Price Indices',
   notes:[
    {h:'What is Inflation?',items:['Inflation is a <b>sustained rise in the general price level</b> of goods and services over time, reducing the purchasing power of money','<b>Demand-Pull</b>: caused by excess demand relative to supply','<b>Cost-Push</b>: caused by rising input/production costs','<b>Stagflation</b>: high inflation + stagnant growth + high unemployment together','<b>Hyperinflation</b>: extremely high & accelerating inflation (e.g., Zimbabwe, Venezuela)','<b>Deflation</b>: sustained fall in general price level','<b>Disinflation</b>: slowing down of the inflation rate (prices still rising, but slower)']},
    {h:'Measuring Inflation in India',items:['<b>CPI (Consumer Price Index)</b>: released by NSO (MoSPI); tracks retail prices faced by consumers; basis for RBI\'s inflation targeting','<b>WPI (Wholesale Price Index)</b>: released by Office of Economic Adviser, DPIIT; tracks wholesale/producer-level prices; excludes services','📌 DON\'T CONFUSE: RBI\'s inflation target is based on <b>CPI (Combined)</b>, NOT WPI']},
    {h:'Tools to Control Inflation',items:['<b>Monetary measures</b>: raise Repo/CRR/SLR to reduce money supply','<b>Fiscal measures</b>: reduce government spending, increase taxes','<b>Supply-side measures</b>: boost production, control hoarding, import liberalization']}
   ],
   pyqs:[
    {q:'Which of the following is the basis of RBI\'s inflation targeting in India?',opts:['WPI','CPI-IW (Industrial Workers)','CPI (Combined/All India)','GDP Deflator'],ans:2,exp:'RBI\'s inflation targeting is based on CPI (Consumer Price Index) — All India/Combined — released by the NSO. The target is 4% ± 2%. This was formalised by the Monetary Policy Framework Agreement signed in February 2015 between RBI and the Government.',yr:'UPSC 2020'},
    {q:'Stagflation refers to:',opts:['High inflation with high growth','High inflation with stagnant growth and high unemployment','Low inflation with high growth','Deflation with low unemployment'],ans:1,exp:'Stagflation is a situation where high inflation occurs simultaneously with stagnant economic growth and high unemployment. It presents a policy dilemma because conventional monetary tightening to fight inflation could worsen unemployment and stagnation.',yr:'UPSC 2016'}
   ]},
  {id:'budget',icon:'💰',title:'Public Finance & Budget',
   notes:[
    {h:'Union Budget',items:['Presented under <b>Article 112</b> as the "Annual Financial Statement"; covers 1 April – 31 March','Presented by Finance Minister, typically on <b>1 February</b> since 2017','<b>Revenue Budget</b>: Revenue Receipts (tax + non-tax) & Revenue Expenditure','<b>Capital Budget</b>: Capital Receipts (loans, disinvestment) & Capital Expenditure (asset creation)','Plan vs Non-Plan Expenditure: classification <b>discontinued since 2017–18</b>; now classified as Capital & Revenue']},
    {h:'Types of Government Deficits',items:['<b>Revenue Deficit</b>: Revenue Expenditure − Revenue Receipts','<b>Fiscal Deficit</b>: Total Expenditure − Total Receipts (excluding borrowings) — <b>most watched indicator</b>','<b>Primary Deficit</b>: Fiscal Deficit − Interest Payments','<b>Effective Revenue Deficit</b>: Revenue Deficit − Grants for creation of capital assets','📌 <b>FRBM Act, 2003</b> (Fiscal Responsibility and Budget Management): legal framework to keep fiscal deficit and govt debt within targeted limits']},
    {h:'Taxation in India',items:['<b>Direct Tax</b>: burden cannot be shifted; paid directly by taxpayer; e.g., Income Tax, Corporate Tax; progressive in nature','<b>Indirect Tax</b>: burden can be shifted to consumer; e.g., GST, Customs Duty; generally regressive','<b>GST (Goods & Services Tax)</b>: launched <b>1 July 2017</b>; single destination-based multi-stage indirect tax; subsumed most central & state indirect taxes; "One Nation, One Tax"','<b>CGST</b>: levied by Central Govt on intra-state supply; <b>SGST</b>: levied by State Govt on intra-state supply; <b>IGST</b>: levied by Centre on inter-state supply & imports','<b>GST Council (Art.279A)</b>: chaired by Union Finance Minister; State Finance Ministers as members','<b>Finance Commission (Art.280)</b>: constitutional body; every 5 years; recommends distribution of tax revenues between Centre & States']}
   ],
   pyqs:[
    {q:'Under which Article of the Constitution is the Annual Financial Statement (Union Budget) presented?',opts:['Article 110','Article 112','Article 149','Article 265'],ans:1,exp:'The Union Budget is presented under Article 112 of the Constitution as the Annual Financial Statement. It contains estimates of receipts and expenditure of the Government of India for the financial year (1 April to 31 March).',yr:'UPSC 2019'},
    {q:'GST in India was launched on:',opts:['1 April 2017','1 July 2017','1 January 2018','26 January 2017'],ans:1,exp:'The Goods and Services Tax (GST) was launched on 1 July 2017 at midnight in the Central Hall of Parliament. It subsumed over 17 central and state taxes, introducing a unified indirect tax system — "One Nation, One Tax, One Market".',yr:'UPSC 2018'},
    {q:'The Fiscal Deficit is calculated as:',opts:['Revenue Expenditure minus Revenue Receipts','Total Expenditure minus Total Receipts excluding borrowings','Total Expenditure minus Total Receipts including borrowings','Primary Deficit minus Interest Payments'],ans:1,exp:'Fiscal Deficit = Total Expenditure − Total Receipts excluding borrowings (net of recoveries). It represents the net borrowing requirement of the government and is the most widely tracked deficit indicator. The FRBM Act, 2003 mandates fiscal consolidation targets.',yr:'UPSC 2017'}
   ]},
  {id:'external',icon:'🌐',title:'External Sector & Economic Reforms',
   notes:[
    {h:'Balance of Payments (BoP)',items:['A systematic record of all economic transactions between residents of a country and the rest of the world over a year','<b>Current Account</b>: trade in goods & services, income, transfers (remittances) — most tracked','<b>Capital Account</b>: capital transfers, acquisition/disposal of non-financial assets','<b>Financial Account</b>: FDI, FPI, loans, banking capital flows','<b>Current Account Deficit (CAD)</b>: when a country\'s imports of goods, services & transfers exceed its exports']},
    {h:'FDI vs FPI & Exchange Rate',items:['<b>FDI (Foreign Direct Investment)</b>: long-term; brings management control/stake; relatively stable, "sticky" capital','<b>FPI (Foreign Portfolio Investment)</b>: short-term; investment in shares/bonds; no control; volatile "hot money"','<b>Fixed Exchange Rate</b>: pegged by government/central bank to another currency/gold','<b>Floating Exchange Rate</b>: determined by market demand & supply','India follows <b>managed float</b> — market-determined with occasional RBI intervention','India has <b>full Current Account convertibility</b>, but only <b>partial Capital Account convertibility</b>','<b>Forex Reserves</b>: foreign currency assets held by RBI — includes foreign currency assets, gold, SDRs, Reserve Tranche Position with IMF']},
    {h:'LPG Reforms (1991)',items:['In 1991, India faced severe BoP crisis — forex reserves fell to cover barely <b>2 weeks of imports</b>','PM Narasimha Rao + FM Manmohan Singh undertook structural reforms with IMF/World Bank support','<b>Liberalization</b>: abolishing industrial licensing (License Raj); easing import restrictions','<b>Privatization</b>: reducing role of public sector; disinvestment in PSUs; opening sectors to private players','<b>Globalization</b>: reducing tariffs; encouraging FDI/FPI; currency reforms (rupee devaluation)','1991 marked India\'s shift from a closed, heavy state-controlled economy to a more open, market-oriented one']}
   ],
   pyqs:[
    {q:'The LPG reforms of 1991 in India were introduced during the tenure of which Finance Minister?',opts:['P. Chidambaram','Pranab Mukherjee','Manmohan Singh','Yashwant Sinha'],ans:2,exp:'The 1991 economic reforms (LPG — Liberalization, Privatization, Globalization) were introduced when Dr. Manmohan Singh was the Finance Minister in the government of Prime Minister P.V. Narasimha Rao. India was facing a severe BoP crisis with forex reserves falling to cover barely 2 weeks of imports.',yr:'UPSC 2018'},
    {q:'Which of the following is considered "hot money" in international finance?',opts:['FDI flows','Remittances from abroad','FPI (Foreign Portfolio Investment)','World Bank loans'],ans:2,exp:'FPI (Foreign Portfolio Investment) is referred to as "hot money" because it can be quickly moved in and out of a country in response to short-term economic or political changes. Unlike FDI, it does not bring managerial control and can be highly volatile.',yr:'UPSC 2016'}
   ]},
  {id:'schemes',icon:'🎯',title:'Key Institutions & Schemes',
   notes:[
    {h:'Important Economic Institutions',items:['<b>RBI</b>: Central bank — monetary policy, currency, banking regulation','<b>SEBI</b>: Regulates securities market & stock exchanges','<b>IRDAI</b>: Regulates insurance sector','<b>NABARD</b>: Apex bank for agriculture & rural development finance','<b>SIDBI</b>: Apex institution for MSME financing','<b>NITI Aayog</b>: Policy think-tank for development strategy (replaced Planning Commission, <b>1 January 2015</b>); Chairperson: Prime Minister; no fund-allocation power unlike Planning Commission','<b>NSO/MoSPI</b>: Compiles national income & statistical data']},
    {h:'Economic Planning',items:['Planning Commission (est. 1950, modeled on Soviet approach) → replaced by <b>NITI Aayog (1 Jan 2015)</b>','Five-Year Plans ran from 1951 to 2017 (12th Plan: 2012–17 was the last)','<b>1st Plan (1951–56)</b>: Agriculture & irrigation; <b>2nd Plan (1956–61)</b>: Industrialization (Mahalanobis model)','<b>8th Plan (1992–97)</b>: Post-LPG market-oriented growth','<b>12th Plan (2012–17)</b>: "Faster, more inclusive & sustainable growth"']},
    {h:'Flagship Government Schemes',items:['<b>Jan Dhan Yojana</b>: Financial inclusion — universal bank account access','<b>MUDRA Yojana</b>: Collateral-free micro-loans to small businesses','<b>Ayushman Bharat</b>: Health insurance cover for vulnerable families','<b>PM Awas Yojana</b>: "Housing for All" — affordable housing','<b>Atmanirbhar Bharat</b>: Self-reliance — domestic manufacturing & supply chains','<b>PLI Schemes (Production Linked Incentive)</b>: boosts domestic manufacturing in strategic sectors','<b>PM-KISAN</b>: income support to farmers; <b>PMFBY</b>: crop insurance; <b>MSP</b>: Minimum Support Price']},
    {h:'Quick Glossary',items:['<b>Gini Coefficient</b>: measures income/wealth inequality (0 = perfect equality, 1 = perfect inequality)','<b>HDI (Human Development Index)</b>: composite index of life expectancy, education & per capita income; released by UNDP','<b>Demographic Dividend</b>: economic growth potential from a large working-age population share','<b>Phillips Curve</b>: inverse relationship between inflation and unemployment','<b>Twin Deficit</b>: simultaneous fiscal deficit and current account deficit','<b>SDR (Special Drawing Rights)</b>: IMF\'s international reserve asset']}
   ],
   pyqs:[
    {q:'NITI Aayog replaced which body on 1 January 2015?',opts:['Finance Commission','Planning Commission','SEBI','National Development Council'],ans:1,exp:'NITI Aayog (National Institution for Transforming India) replaced the Planning Commission on 1 January 2015. Unlike the Planning Commission, NITI Aayog is a policy think-tank and does not have the power to allocate funds to ministries or states. The Prime Minister is its Chairperson.',yr:'UPSC 2018'},
    {q:'The Gini Coefficient measures:',opts:['Economic growth rate','Income/wealth inequality','Inflation rate','Human Development Index'],ans:1,exp:'The Gini Coefficient (or Gini Index) is a statistical measure of income or wealth inequality within a nation. A value of 0 represents perfect equality (everyone has the same income) while a value of 1 represents perfect inequality (one person has all the income).',yr:'UPSC 2016'},
    {q:'NABARD is the apex institution for:',opts:['Foreign trade financing','Agriculture and rural development finance','Industrial financing','Insurance regulation'],ans:1,exp:'NABARD (National Bank for Agriculture and Rural Development) is the apex development bank for agriculture and rural development in India. It refinances credit to cooperative banks and Regional Rural Banks (RRBs) and also provides direct credit for agricultural and rural projects.',yr:'UPSC 2019'}
   ]}
];

