let HUB_S = {subj:'history', histTab:'ancient', geoTab:'world', chapIdx:0, contentTab:'notes'};

// Override render to target hub-content-area instead of content-area
function hubRender(){
  S = HUB_S; // Keep S in sync for legacy functions
  const area = document.getElementById('hub-content-area');
  if(!area) return;
  const d = SUBJECTS[HUB_S.subj];
  if(!d){ area.innerHTML=''; return; }
  const gs = (d.gs||[]).map(g=>{
    const st=GS_STYLE[g]||{};
    return `<span class="gs-tag" style="background:${st.bg||''};color:${st.col||''};border-color:${st.bd||''}">${g}</span>`;
  }).join('');
  let html = `<div class="subj-banner">
    <div class="bn-icon">${d.icon}</div>
    <div><div class="bn-title">${d.label}</div><div class="bn-sub">${d.desc}</div></div>
    <div class="gs-tags">${gs}</div>
  </div>`;
  if(HUB_S.subj==='history') html += hubRenderHistory();
  else if(HUB_S.subj==='geo') html += hubRenderGeo();
  else if(['polity','economy','science','ir','governance','intsec','ca','env','socialjustice','artculture'].includes(HUB_S.subj)) html += hubRenderFlat();
  else html += renderComingSoon(d);
  area.innerHTML = html;
}

