const SUBJECT_LABELS = {
  history:'History',artculture:'Art & Culture',polity:'Polity',economy:'Economy',
  science:'Science & Tech',ir:'Intl. Relations',env:'Environment',geo:'Geography',
  ca:'Current Affairs',governance:'Governance',socialjustice:'Social Justice',intsec:'Internal Security'
};

window.openHubSubject = function(subj){
  if(!state.user){ toast('Create a free account first'); openAuth(); return; }
  if(store.plan !== 'prime'){
    toast('GS Quick Revision is a Prime feature — upgrade to unlock');
    document.getElementById('pricing').scrollIntoView({behavior:'smooth'});
    return;
  }
  const modal = document.getElementById('hubModal');
  const title = document.getElementById('hubModalTitle');
  title.textContent = 'Quick Revision Hub — ' + (SUBJECT_LABELS[subj]||subj);
  modal.classList.add('open');
  document.body.style.overflow = 'hidden';
  // Switch to the requested subject in the inline hub
  HUB_S = {subj:subj, histTab:'ancient', geoTab:'world', chapIdx:0, contentTab:'notes'};
  // Update sidebar active state
  document.querySelectorAll('#hubSidebar .sid-btn').forEach(b=>{
    b.classList.remove('active');
    b.style.borderLeftColor='transparent';
    b.style.color='';
  });
  const colors = {history:'var(--gold)',polity:'var(--navy)',economy:'var(--green)',science:'var(--purple)',ir:'var(--teal)',env:'var(--green)',geo:'var(--saffron)',ca:'var(--crimson)',governance:'var(--teal)',intsec:'var(--crimson)',socialjustice:'var(--crimson)',artculture:'var(--gold)'};
  // Find the button for this subject and activate it
  document.querySelectorAll('#hubSidebar .sid-btn').forEach(b=>{
    if(b.getAttribute('onclick') && b.getAttribute('onclick').includes("'"+subj+"'")){
      b.classList.add('active');
      b.style.borderLeftColor = colors[subj]||'var(--navy)';
      b.style.color = colors[subj]||'var(--navy)';
    }
  });
  hubRender();
};

window.closeHubModal = function(){
  const modal = document.getElementById('hubModal');
  modal.classList.remove('open');
  document.body.style.overflow = '';
};

// Close on backdrop click
document.getElementById('hubModal').addEventListener('click', function(e){
  if(e.target === this) closeHubModal();
});

// Close on Escape key
document.addEventListener('keydown', function(e){
  if(e.key==='Escape' && document.getElementById('hubModal').classList.contains('open')) closeHubModal();
});

// Initial render of hub (history by default) — will be shown when modal opens
hubRender();
